describe("parseToolResult", () => {
  it("prefers structuredContent over the Markdown content block", () => {
    // A tool that renders Markdown for chat still exposes JSON for the client.
    const result = {
      content: [{ type: "text", text: "| Nodes | 2 |" }],
      structuredContent: { nodes: 2, active_edges: 5 },
    };
    expect(parseToolResult(result)).toEqual({ nodes: 2, active_edges: 5 });
  });

  it("parses JSON from the first text content block", () => {
    const result = { content: [{ type: "text", text: '{"nodes":2}' }] };
    expect(parseToolResult(result)).toEqual({ nodes: 2 });
  });

  it("returns the raw text when it is not JSON", () => {
    const result = { content: [{ type: "text", text: "not json" }] };
    expect(parseToolResult(result)).toBe("not json");
  });

  it("returns the whole result when there is no text block", () => {
    const result = { content: [] };
    expect(parseToolResult(result)).toBe(result);
  });
});

describe("resolveServerPath", () => {
  it("honours an explicit non-default configured path", () => {
    expect(resolveServerPath("/custom/mindleak-mcp", "/ws", { exists: () => true })).toBe(
      "/custom/mindleak-mcp"
    );
  });

  it("prefers a packaged server over a workspace build", () => {
    const resolved = resolveServerPath("mindleak-mcp", "/ws", {
      extensionPath: "/extension",
      platform: "linux",
      exists: (candidate) =>
        candidate === path.join("/extension", "bin", "mindleak-mcp") ||
        candidate === path.join("/ws", "target", "release", "mindleak-mcp"),
    });

    expect(resolved).toBe(path.join("/extension", "bin", "mindleak-mcp"));
  });

  it("uses a workspace build when the packaged server is absent", () => {
    const resolved = resolveServerPath("mindleak-mcp", "/ws", {
      extensionPath: "/extension",
      platform: "linux",
      exists: (candidate) => candidate === path.join("/ws", "target", "release", "mindleak-mcp"),
    });

    expect(resolved).toBe(path.join("/ws", "target", "release", "mindleak-mcp"));
  });

  it("prefers a release build when it exists (win32)", () => {
    const resolved = resolveServerPath("mindleak-mcp", "C:/ws", {
      platform: "win32",
      exists: (p) => p.includes("release"),
    });
    expect(resolved).toContain("release");
    expect(resolved).toContain("mindleak-mcp.exe");
  });

  it("falls back to debug when release is absent", () => {
    const resolved = resolveServerPath("mindleak-mcp", "/ws", {
      platform: "linux",
      exists: (p) => p.includes("debug"),
    });
    expect(resolved).toContain("debug");
    expect(resolved.endsWith("mindleak-mcp")).toBe(true);
  });

  it("falls back to the bare command when no build is found", () => {
    expect(resolveServerPath("mindleak-mcp", "/ws", { exists: () => false })).toBe("mindleak-mcp");
  });
});

describe("resolveBinaryPath", () => {
  it("resolves a workspace lodestar build (linux)", () => {
    const resolved = resolveBinaryPath("lodestar-mcp", "/ws", "lodestar-mcp", {
      platform: "linux",
      exists: (p) => p.includes("release"),
    });
    expect(resolved).toContain("release");
    expect(resolved.endsWith("lodestar-mcp")).toBe(true);
  });

  it("honours an explicit non-default path", () => {
    expect(
      resolveBinaryPath("/opt/lodestar-mcp", "/ws", "lodestar-mcp", { exists: () => true })
    ).toBe("/opt/lodestar-mcp");
  });

  it("prefers the shared install over a worktree build (ADR-0073)", () => {
    // ADR-0073 installs one binary per machine precisely so 56 worktrees do not
    // each carry their own. Preferring a worktree build here would quietly undo
    // that and reintroduce the stale-binary problem it was chosen to avoid.
    const resolved = resolveBinaryPath("lodestar-mcp", "/ws", "lodestar-mcp", {
      platform: "linux",
      homeDir: "/home/dev",
      exists: () => true,
    });
    expect(resolved).toContain(".mindleak");
    expect(resolved).not.toContain("target");
  });

  it("still falls back to a worktree build when nothing is installed", () => {
    const resolved = resolveBinaryPath("lodestar-mcp", "/ws", "lodestar-mcp", {
      platform: "linux",
      homeDir: "/home/dev",
      exists: (p) => p.includes("target"),
    });
    expect(resolved).toContain("release");
  });

  it("prefers the packaged binary over everything else", () => {
    const resolved = resolveBinaryPath("lodestar-mcp", "/ws", "lodestar-mcp", {
      platform: "linux",
      homeDir: "/home/dev",
      extensionPath: "/ext",
      exists: () => true,
    });
    expect(resolved).toBe("/ext/bin/lodestar-mcp".replace(/\//g, path.sep));
  });
});

describe("planMcpServers", () => {
  const configured = { memory: "mindleak-mcp", intent: "lodestar-mcp" };

  it("contributes both planes", () => {
    const plans = planMcpServers("/ws", "copilot", configured, { exists: () => false });
    expect(plans.map((p) => p.id)).toEqual(["mindleak", "lodestar"]);
  });

  it("roots every server at the workspace folder that provides it", () => {
    // ADR-0073: a window edits its own worktree, so a server started for that
    // window must resolve repo-relative ids against that worktree and no other.
    const plans = planMcpServers("/ws/sibling", "copilot", configured, { exists: () => false });
    for (const plan of plans) {
      expect(plan.cwd).toBe("/ws/sibling");
      expect(plan.env.MINDLEAK_WORKSPACE).toBe("/ws/sibling");
    }
  });

  it("reuses the extension's binary resolution instead of a second rule", () => {
    const plans = planMcpServers("/ws", "copilot", configured, {
      platform: "linux",
      exists: (p) => p.includes("release"),
    });
    expect(plans[0].command).toContain("release");
    expect(plans[0].command.endsWith("mindleak-mcp")).toBe(true);
    expect(plans[1].command).toContain("release");
    expect(plans[1].command.endsWith("lodestar-mcp")).toBe(true);
  });

  it("honours an explicitly configured binary path", () => {
    const plans = planMcpServers(
      "/ws",
      "copilot",
      { memory: "/opt/mindleak-mcp", intent: "/opt/lodestar-mcp" },
      { exists: () => false }
    );
    expect(plans.map((p) => p.command)).toEqual(["/opt/mindleak-mcp", "/opt/lodestar-mcp"]);
  });

  it("gives each plane its own attribution variable", () => {
    const plans = planMcpServers("/ws", "copilot", configured, { exists: () => false });
    expect(plans[0].env.MINDLEAK_AGENT).toBe("copilot");
    expect(plans[0].env.LODESTAR_AGENT).toBeUndefined();
    expect(plans[1].env.LODESTAR_AGENT).toBe("copilot");
    expect(plans[1].env.MINDLEAK_AGENT).toBeUndefined();
  });

  it("emits a database override only when one is configured", () => {
    const bare = planMcpServers("/ws", "copilot", configured, { exists: () => false });
    expect(bare[0].env.MINDLEAK_DB).toBeUndefined();
    expect(bare[1].env.LODESTAR_DB).toBeUndefined();

    const overridden = planMcpServers(
      "/ws",
      "copilot",
      { ...configured, memoryDatabase: "/tmp/m.db", intentDatabase: "/tmp/i.db" },
      { exists: () => false }
    );
    expect(overridden[0].env.MINDLEAK_DB).toBe("/tmp/m.db");
    expect(overridden[1].env.LODESTAR_DB).toBe("/tmp/i.db");
  });

  it("resolves both planes to the shared install when one is present", () => {
    const plans = planMcpServers("/ws", "copilot", configured, {
      platform: "linux",
      homeDir: "/home/dev",
      exists: () => true,
    });
    expect(plans[0].command).toContain(".mindleak");
    expect(plans[1].command).toContain(".mindleak");
  });

  it("changes the definition version when a resolved binary is replaced", () => {
    let generation = 1;
    const options = {
      platform: "linux" as const,
      exists: () => true,
      version: () => `generation-${generation}`,
    };

    const before = planMcpServers("/ws", "copilot", configured, options);
    generation = 2;
    const after = planMcpServers("/ws", "copilot", configured, options);

    expect(after.map((plan) => plan.command)).toEqual(before.map((plan) => plan.command));
    expect(before.map((plan) => plan.version)).toEqual(["generation-1", "generation-1"]);
    expect(after.map((plan) => plan.version)).toEqual(["generation-2", "generation-2"]);
  });
});

describe("boardRows", () => {
  it("orders by lifecycle and formats the owner", () => {
    const rows = boardRows(
      [
        { id: "t1", goal_id: "g", title: "done thing", status: "done" },
        {
          id: "t2",
          goal_id: "g",
          title: "mine",
          status: "claimed",
          owner: "alice",
          lease_expires_at: 200,
          scope: { paths: ["src/auth.ts"], symbols: ["symbol:src/auth.ts:validate"] },
        },
      ],
      true,
      100
    );
    expect(rows[0].label).toBe("mine");
    expect(rows[0].description).toContain("In progress · alice");
    expect(rows[0].description).toContain("2 scoped");
    expect(rows[0].tooltip).toContain("scope paths: src/auth.ts");
    expect(rows[0].tooltip).toContain("scope symbols: symbol:src/auth.ts:validate");
    expect(rows[1].status).toBe("done");
  });

  /**
   * An expired claim is claimable — the store's compare-and-swap admits
   * `status = 'claimed' AND lease_expires_at < now`, and the row already says
   * "Claim expired · Ready". Ranking it as `claimed` put abandoned work among
   * work in progress: one session left fifteen such rows in a day, which buried
   * the three tasks anyone was actually holding and made the board unreadable.
   */
  it("does not let lapsed claims bury the work someone is holding", () => {
    const rows = boardRows(
      [
        { id: "lapsed1", goal_id: "g", title: "lapsed1", status: "claimed", lease_expires_at: 50 },
        { id: "lapsed2", goal_id: "g", title: "lapsed2", status: "claimed", lease_expires_at: 60 },
        { id: "live", goal_id: "g", title: "live", status: "claimed", lease_expires_at: 900 },
      ],
      false,
      100
    );

    expect(rows[0].id).toBe("live");
  });

  it("ranks a lapsed claim as ready, below work nobody has started", () => {
    const rows = boardRows(
      [
        { id: "lapsed", goal_id: "g", title: "lapsed", status: "claimed", lease_expires_at: 50 },
        { id: "untouched", goal_id: "g", title: "untouched", status: "open" },
      ],
      false,
      100
    );

    // Both are claimable; work nobody has started outranks work someone dropped.
    expect(rows.map((row) => row.id)).toEqual(["untouched", "lapsed"]);
  });

  /**
   * Regression: the sort knew a lapsed claim was ready work, and the icon did
   * not. Both a live claim and an expired one drew `account` — the icon that
   * means "someone is holding this" — so the single row that means "abandoned,
   * take it" was indistinguishable from the rows that mean "hands off". The
   * board said the right thing in its order and the wrong thing in its icons.
   */
  it("gives an expired claim its own icon instead of the owner icon", () => {
    const rows = boardRows(
      [
        { id: "live", goal_id: "g", title: "live", status: "claimed", lease_expires_at: 900 },
        { id: "lapsed", goal_id: "g", title: "lapsed", status: "claimed", lease_expires_at: 50 },
      ],
      false,
      100
    );

    const icons = new Map(rows.map((row) => [row.id, row.icon]));
    expect(icons.get("live")).toBe("account");
    expect(icons.get("lapsed")).not.toBe("account");
    expect(icons.get("lapsed")).toBe("watch");
  });

  it("keeps an icon for every board status and falls back rather than blanking", () => {
    const at = (status: string) => boardIconId({ id: "t", goal_id: "g", title: "t", status }, 100);

    expect(at("open")).toBe("circle-outline");
    expect(at("in_review")).toBe("eye");
    expect(at("needs_input")).toBe("comment-unresolved");
    expect(at("paused")).toBe("debug-pause");
    expect(at("blocked")).toBe("error");
    expect(at("done")).toBe("check");
    // An unknown status must still render something.
    expect(at("something_new")).toBe("circle-slash");
  });

  it("treats a claim with no lease as expired, not as owned", () => {
    // A claimed row carrying no lease_expires_at cannot be live; taskLeaseState
    // already says "expired", and the icon must agree rather than imply an owner.
    expect(boardIconId({ id: "t", goal_id: "g", title: "t", status: "claimed" }, 100)).toBe(
      "watch"
    );
  });

  it("hides terminal history by default and retains an explicit history view", () => {
    const tasks = [
      { id: "open", goal_id: "g", title: "open", status: "open" },
      { id: "done", goal_id: "g", title: "done", status: "done" },
      { id: "abandoned", goal_id: "g", title: "abandoned", status: "abandoned" },
    ];

    expect(boardRows(tasks).map((row) => row.id)).toEqual(["open"]);
    expect(boardRows(tasks, true).map((row) => row.id)).toEqual(["open", "done", "abandoned"]);
  });

  it("puts review decisions before ready work and uses action-oriented labels", () => {
    const rows = boardRows(
      [
        { id: "ready", goal_id: "g", title: "ready", status: "open" },
        { id: "review", goal_id: "g", title: "review", status: "in_review" },
        { id: "done", goal_id: "g", title: "done", status: "done" },
      ],
      true
    );

    expect(rows.map((row) => row.id)).toEqual(["review", "ready", "done"]);
    expect(rows[0].description).toBe("Review needed");
    expect(rows[1].description).toBe("Ready");
    expect(rows[2].description).toBe("Verified");
    expect(rows[0].tooltip).toContain("status: Review needed");
  });

  // ADR-0035 decision 5: the board row carries not just who holds a task but
  // the branch they hold it on — what a colliding agent needs to tell a merge
  // risk from the same work twice. Omitted cleanly when none was declared,
  // never guessed.
  it("surfaces the owner's branch on the row, and omits it cleanly when none was declared", () => {
    const rows = boardRows(
      [
        {
          id: "onbranch",
          goal_id: "g",
          title: "onbranch",
          status: "claimed",
          owner: "alice",
          branch: "fleet/surface",
          lease_expires_at: 900,
        },
        {
          id: "nobranch",
          goal_id: "g",
          title: "nobranch",
          status: "claimed",
          owner: "bob",
          lease_expires_at: 900,
        },
      ],
      false,
      100
    );
    const byId = new Map(rows.map((row) => [row.id, row]));
    // The branch a colliding agent needs, right in the row and its tooltip.
    expect(byId.get("onbranch")!.description).toContain("alice on fleet/surface");
    expect(byId.get("onbranch")!.tooltip).toContain("branch: fleet/surface");
    // No branch declared: the owner still shows, the branch does not, and
    // nothing is invented.
    expect(byId.get("nobranch")!.description).toContain("bob");
    expect(byId.get("nobranch")!.description).not.toContain(" on ");
    expect(byId.get("nobranch")!.tooltip).not.toContain("branch:");
  });
});

describe("formatGoverningClauses", () => {
  const clause = (over: Partial<GoverningClause> = {}): GoverningClause => ({
    node_id: "artifact:src/pay.rs",
    goal: { id: "goal:pay", title: "Payments boundary", kind: "constraint" },
    mode: "governed",
    ...over,
  });

  it("returns empty string when nothing governs", () => {
    expect(formatGoverningClauses(undefined)).toBe("");
    expect(formatGoverningClauses([])).toBe("");
  });

  it("renders a bounded 'Governed by' section with title, kind, and mode", () => {
    const text = formatGoverningClauses([
      clause(),
      clause({
        goal: { id: "goal:frozen", title: "Frozen schema", kind: "invariant" },
        mode: "forbid_change",
      }),
    ]);
    expect(text).toContain("Governed by:");
    expect(text).toContain("Payments boundary (constraint, governed)");
    expect(text).toContain("Frozen schema (invariant, forbid_change)");
  });

  it("surfaces governing clauses in a claimed board row's tooltip", () => {
    const rows = boardRows([
      {
        id: "t",
        goal_id: "goal:pay",
        title: "Wire payments",
        status: "claimed",
        owner: "agent-a",
        governing: [clause()],
      },
    ]);
    expect(rows[0].tooltip).toContain("Governed by:");
    expect(rows[0].tooltip).toContain("Payments boundary");
  });
});

