describe("telemetryDashboard", () => {
  // Bug: a visible telemetry pane polled every three seconds with Live off,
  // dominating telemetry and wasting compute. Only the opt-in live stream
  // should run the timer; open, toggle and manual refresh remain event-driven.
  it("polls periodically only when the visible pane has Live enabled", () => {
    expect(shouldPollTelemetry(false, false)).toBe(false);
    expect(shouldPollTelemetry(false, true)).toBe(false);
    expect(shouldPollTelemetry(true, false)).toBe(false);
    expect(shouldPollTelemetry(true, true)).toBe(true);
  });

  it("derives success/error rates, weighted latency, and sorted tool rows", () => {
    const dashboard = telemetryDashboard(SNAPSHOT, { nodes: 42, active_edges: 17 });
    expect(dashboard.nodes).toBe(42);
    expect(dashboard.activeEdges).toBe(17);
    expect(dashboard.totalEvents).toBe(10);
    expect(dashboard.totalErrors).toBe(2);
    expect(dashboard.successRatePct).toBe(80);
    expect(dashboard.errorRatePct).toBe(20);
    // weighted: (300 + 40) / (6 + 4) = 34
    expect(dashboard.avgLatencyMs).toBe(34);
    expect(dashboard.tools.map((t) => t.name)).toEqual(["recall", "graph_stats"]);
    expect(dashboard.tools[0]).toMatchObject({
      calls: 6,
      errors: 2,
      errorRatePct: 33.3,
      avgMs: 50,
      currentlyFailing: true,
    });
  });

  it("uses graph health bundled into the telemetry snapshot", () => {
    const dashboard = telemetryDashboard({
      ...SNAPSHOT,
      graph: { nodes: 23, active_edges: 41 },
      retrospective: {
        background_read_calls: 81_724,
        preflight_read_calls: 265,
        architectural_decision_calls: 13,
        writing_sessions: 4,
        writing_sessions_without_memory_read: 3,
        recommendations: ["Run check_overlap before editing."],
      },
    });

    expect(dashboard.nodes).toBe(23);
    expect(dashboard.activeEdges).toBe(41);
    expect(dashboard.backgroundReadCalls).toBe(81_724);
    expect(dashboard.preflightReadCalls).toBe(265);
    expect(dashboard.memoryPreflightMisses).toBe(3);
    expect(dashboard.recommendations).toEqual(["Run check_overlap before editing."]);
  });

  it("reports live failing-tool health distinct from the lifetime error tally", () => {
    // Regression: a tool with a resolved historical error (lifetime errors = 1)
    // whose most recent call succeeded must read as healthy — not an active
    // fault. failingTools is the live signal; totalErrors stays cumulative.
    const snapshot: TelemetrySnapshot = {
      total_events: 3,
      total_errors: 1,
      currently_failing_tools: 0,
      by_name: [
        {
          name: "recall",
          calls: 2,
          errors: 1,
          total_ms: 30,
          min_ms: 10,
          max_ms: 20,
          avg_ms: 15,
          last_error_at: 100,
          last_success_at: 200,
          last_error_detail: { error: "transient boom" },
          currently_failing: false,
        },
      ],
      recent: [],
    };
    const dashboard = telemetryDashboard(snapshot, { nodes: 1, active_edges: 0 });
    expect(dashboard.totalErrors).toBe(1);
    expect(dashboard.failingTools).toBe(0);
    expect(dashboard.tools[0].currentlyFailing).toBe(false);
  });

  it("flags a tool as failing when its latest call errored", () => {
    const snapshot: TelemetrySnapshot = {
      total_events: 2,
      total_errors: 1,
      currently_failing_tools: 1,
      by_name: [
        {
          name: "embed",
          calls: 2,
          errors: 1,
          total_ms: 14,
          min_ms: 5,
          max_ms: 9,
          avg_ms: 7,
          last_error_at: 200,
          last_success_at: 100,
          currently_failing: true,
        },
      ],
      recent: [],
    };
    const dashboard = telemetryDashboard(snapshot, undefined);
    expect(dashboard.failingTools).toBe(1);
    expect(dashboard.tools[0].currentlyFailing).toBe(true);
  });

  it("reports skipped optional maintenance as degraded rather than failing", () => {
    const snapshot: TelemetrySnapshot = {
      total_events: 1,
      total_errors: 0,
      currently_failing_tools: 0,
      currently_degraded_tools: 1,
      by_name: [
        {
          name: "autonomous_index",
          calls: 1,
          errors: 0,
          total_ms: 9,
          min_ms: 9,
          max_ms: 9,
          avg_ms: 9,
          currently_failing: false,
          currently_degraded: true,
        },
      ],
      recent: [],
    };

    const dashboard = telemetryDashboard(snapshot);

    expect(dashboard.failingTools).toBe(0);
    expect(dashboard.degradedTools).toBe(1);
    expect(dashboard.tools[0]).toMatchObject({
      currentlyFailing: false,
      currentlyDegraded: true,
    });
  });

  it("reports a clean 100% success readout when nothing has run yet", () => {
    const dashboard = telemetryDashboard(undefined, undefined);
    expect(dashboard).toMatchObject({
      nodes: 0,
      activeEdges: 0,
      totalEvents: 0,
      totalErrors: 0,
      failingTools: 0,
      degradedTools: 0,
      successRatePct: 100,
      errorRatePct: 0,
      avgLatencyMs: 0,
      tools: [],
    });
  });
});

